('q_bece_math_2024_04', 'topic_bece_numbers', 'subj_bece_math', 'What is the LCM of 12 and 18?', 'multiple_choice', '["A. 6", "B. 36", "C. 72", "D. 216"]', 'B', 'LCM(12,18) = 36. Multiples of 12: 12,24,36... Multiples of 18: 18,36...', 'medium', 1, 90),
('q_bece_math_2024_05', 'topic_bece_numbers', 'subj_bece_math', 'Simplify: 2³ × 2²', 'multiple_choice', '["A. 2⁵", "B. 2⁶", "C. 4⁵", "D. 2¹"]', 'A', 'When multiplying powers with same base, add exponents: 2³⁺² = 2⁵', 'medium', 1, 60),
