('q_bece_math_2024_08', 'topic_bece_numbers', 'subj_bece_math', 'Convert 5/8 to a decimal.', 'multiple_choice', '["A. 0.625", "B. 0.58", "C. 0.85", "D. 0.525"]', 'A', '5 ÷ 8 = 0.625', 'easy', 1, 60),
('q_bece_math_2024_09', 'topic_bece_numbers', 'subj_bece_math', 'If a = 3 and b = 4, find the value of a² + b²', 'multiple_choice', '["A. 7", "B. 12", "C. 25", "D. 49"]', 'C', '3² + 4² = 9 + 16 = 25', 'medium', 1, 60),
